export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/** Months a single period of the interval spans — the multiplier for a full-period charge. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

function daysInMonth(year: number, month: number): number {
  return new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
}

/**
 * Adds whole calendar months, clamping the day to the target month's last day
 * when it has no such day (31 Jan + 1 month → 28 Feb). Because every new
 * period starts exactly where the previous one ended, a clamped day simply
 * carries forward into the next calculation on its own (28 Feb → 28 Mar).
 */
function addCalendarMonths(date: Date, months: number): Date {
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth();
  const day = date.getUTCDate();

  const total = month + months;
  const targetYear = year + Math.floor(total / 12);
  const targetMonth = ((total % 12) + 12) % 12;
  const clampedDay = Math.min(day, daysInMonth(targetYear, targetMonth));

  return new Date(
    Date.UTC(
      targetYear,
      targetMonth,
      clampedDay,
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds(),
      date.getUTCMilliseconds(),
    ),
  );
}

/**
 * The end of the next billing period: one month out for a monthly interval,
 * twelve for annual, both via `addCalendarMonths` so month-end clamping
 * (31 Jan → 28 Feb, 29 Feb → 28 Feb) is handled the same way for either.
 */
export function addBillingPeriod(
  value: IsoTimestamp,
  interval: BillingInterval,
): IsoTimestamp {
  return toIsoTimestamp(addCalendarMonths(parseIso(value), monthsInInterval(interval)));
}

