export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * Inserts the invoice row and announces it once — the one place that happens,
 * shared by the renewal job and the mid-period proration paths above. A zero
 * (or negative) charge produces no invoice.
 */
export async function issueInvoice(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  amountCents: number,
  actorId: UserId | null,
  occurredAt: IsoTimestamp,
): Promise<Invoice | null> {
  if (amountCents <= 0) return null;

  const number = await nextInvoiceNumber(orgId);
  const invoice = await invoiceRepo.insertInvoice(orgId, {
    orgId,
    number,
    amountCents,
    currency: "usd",
    periodStart,
    periodEnd,
    paidAt: null,
  });

  await emit("billing.invoice_issued", {
    orgId,
    actorId,
    occurredAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}

async function nextInvoiceNumber(orgId: OrgId): Promise<string> {
  const count = await invoiceRepo.countInvoices(orgId);
  return `INV-${String(count + 1).padStart(4, "0")}`;
}

/** Whole days between a period's start and end, at least one. */
function daysInPeriod(periodStart: IsoTimestamp, periodEnd: IsoTimestamp): number {
  const span = parseIso(periodEnd).getTime() - parseIso(periodStart).getTime();
  return Math.max(1, Math.round(span / DAY_MS));
}

/** Whole or started days from `now` to the period end; zero once it has passed. */
function daysLeft(now: Date, periodEnd: IsoTimestamp): number {
  const remainingMs = parseIso(periodEnd).getTime() - now.getTime();
  return remainingMs <= 0 ? 0 : Math.ceil(remainingMs / DAY_MS);
}

/** Scales a full-period charge by the days left over the days in the period, rounded down. */
function prorate(
  fullChargeCents: number,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  now: Date,
): number {
  const left = daysLeft(now, periodEnd);
  if (left === 0) return 0;
  return Math.floor((fullChargeCents * left) / daysInPeriod(periodStart, periodEnd));
}

