/**
 * Rolls every workspace's subscription period forward once it has ended,
 * invoicing each renewed paid period, and ends cancellations that have
 * reached their date.
 *
 * Must call (do not reimplement): emit, getPlanLimits, addBillingPeriod,
 * monthsInInterval, issueInvoice
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addBillingPeriod, monthsInInterval } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const logger = createLogger("billing-renewal-job");

/**
 * An active subscription whose period has ended is rolled forward one
 * interval at a time until its period ends in the future — a subscription
 * several intervals behind gets several consecutive periods, each invoiced on
 * its own. A canceled subscription past its cancellation date instead drops
 * to the free plan as of that date. Trialing and past_due subscriptions are
 * left alone; replaying the job at the same instant is a no-op because every
 * subscription it touches ends up with a period end in the future.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);
    const subscriptions = await subscriptionRepo.listAllSubscriptions();

    for (const subscription of subscriptions) {
      try {
        if (subscription.status === "active") {
          await renew(subscription, stamp);
          result.processed += 1;
        } else if (
          subscription.status === "canceled" &&
          subscription.cancelAt !== null &&
          subscription.cancelAt <= stamp
        ) {
          await endCancellation(subscription, subscription.cancelAt, stamp);
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function renew(subscription: Subscription, stamp: IsoTimestamp): Promise<void> {
  let current = subscription;

  while (current.currentPeriodEnd <= stamp) {
    const periodStart = current.currentPeriodEnd;
    const periodEnd = addBillingPeriod(periodStart, current.interval);

    if (current.plan !== "free") {
      const amountCents =
        getPlanLimits(current.plan).priceCentsPerSeatMonthly *
        current.seats *
        monthsInInterval(current.interval);

      await issueInvoice(
        current.orgId,
        periodStart,
        periodEnd,
        amountCents,
        null,
        stamp,
      );
    }

    current = await subscriptionRepo.advancePeriod(
      current.orgId,
      periodStart,
      periodEnd,
    );
  }
}

async function endCancellation(
  subscription: Subscription,
  cancelAt: IsoTimestamp,
  stamp: IsoTimestamp,
): Promise<void> {
  const periodEnd = addBillingPeriod(cancelAt, "monthly");
  const fromPlan = subscription.plan;

  await subscriptionRepo.endCancellation(subscription.orgId, cancelAt, periodEnd);

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: stamp,
    from: fromPlan,
    to: "free",
  });
}

