import { describe, expect, it } from "vitest";
import { addBillingPeriod, monthsInInterval } from "@/lib/date";
import { toIsoTimestamp } from "@/types/common";

describe("sanity: addBillingPeriod", () => {
  it("clamps 31 Jan to 28 Feb in a non-leap year", () => {
    expect(
      addBillingPeriod(toIsoTimestamp(new Date("2025-01-31T10:00:00.000Z")), "monthly"),
    ).toBe(toIsoTimestamp(new Date("2025-02-28T10:00:00.000Z")));
  });

  it("clamps 31 Jan to 29 Feb in a leap year", () => {
    expect(
      addBillingPeriod(toIsoTimestamp(new Date("2024-01-31T10:00:00.000Z")), "monthly"),
    ).toBe(toIsoTimestamp(new Date("2024-02-29T10:00:00.000Z")));
  });

  it("carries a clamped day forward: 28 Feb -> 28 Mar", () => {
    expect(
      addBillingPeriod(toIsoTimestamp(new Date("2025-02-28T10:00:00.000Z")), "monthly"),
    ).toBe(toIsoTimestamp(new Date("2025-03-28T10:00:00.000Z")));
  });

  it("clamps annual 29 Feb to 28 Feb next (non-leap) year", () => {
    expect(
      addBillingPeriod(toIsoTimestamp(new Date("2024-02-29T10:00:00.000Z")), "annual"),
    ).toBe(toIsoTimestamp(new Date("2025-02-28T10:00:00.000Z")));
  });

  it("handles an ordinary month with no clamping", () => {
    expect(
      addBillingPeriod(toIsoTimestamp(new Date("2025-06-15T00:00:00.000Z")), "monthly"),
    ).toBe(toIsoTimestamp(new Date("2025-07-15T00:00:00.000Z")));
  });

  it("months in interval", () => {
    expect(monthsInInterval("monthly")).toBe(1);
    expect(monthsInInterval("annual")).toBe(12);
  });
});

