import { afterAll, beforeAll, describe, expect, it } from "vitest";

vi_mock();
function vi_mock() {}

import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("sanity: billing renewal job", () => {
  it("renews a paid active subscription past period end and invoices it", async () => {
    const tenant = await createTenant("renewal-paid", "starter");
    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    // Force status active (fixture leaves it trialing) and move period into the past.
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "starter", "monthly");
    await subscriptionRepo.updateSeatCount(tenant.org.id, 3);
    await subscriptionRepo.advancePeriod(
      tenant.org.id,
      toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")),
    );

    const now = new Date("2026-02-15T00:00:00.000Z");
    const result = await runBillingRenewalJob(now);
    expect(result.failed).toBe(0);

    const updated = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(updated?.currentPeriodStart).toBe(toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")));
    expect(updated?.currentPeriodEnd).toBe(toIsoTimestamp(new Date("2026-03-01T00:00:00.000Z")));

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(1);
    expect(invoices[0].amountCents).toBe(900 * 3 * 1);
    expect(invoices[0].periodStart).toBe(toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")));
    expect(invoices[0].periodEnd).toBe(toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")));

    // Replay: running again at the same instant changes nothing.
    await runBillingRenewalJob(now);
    const invoicesAfterReplay = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoicesAfterReplay.length).toBe(1);
    void sub;
  });

  it("catches up a subscription three periods behind with three invoices", async () => {
    const tenant = await createTenant("renewal-behind", "starter");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "starter", "monthly");
    await subscriptionRepo.updateSeatCount(tenant.org.id, 1);
    await subscriptionRepo.advancePeriod(
      tenant.org.id,
      toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z")),
    );

    const now = new Date("2026-04-15T00:00:00.000Z");
    await runBillingRenewalJob(now);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(3);

    const updated = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(updated?.currentPeriodEnd).toBe(toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z")));
  });

  it("moves a canceled subscription past its cancel date to free, once, with no invoice", async () => {
    const tenant = await createTenant("renewal-cancel", "growth");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "growth", "monthly");
    await subscriptionRepo.cancelSubscription(
      tenant.org.id,
      toIsoTimestamp(new Date("2026-01-10T00:00:00.000Z")),
    );

    const now = new Date("2026-01-20T00:00:00.000Z");
    await runBillingRenewalJob(now);

    const updated = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(updated?.plan).toBe("free");
    expect(updated?.status).toBe("active");
    expect(updated?.cancelAt).toBeNull();
    expect(updated?.currentPeriodStart).toBe(toIsoTimestamp(new Date("2026-01-10T00:00:00.000Z")));

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(0);

    await runBillingRenewalJob(now);
    const updatedAgain = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(updatedAgain?.updatedAt).toBe(updated?.updatedAt);
  });

  it("leaves a canceled subscription alone before its cancel date", async () => {
    const tenant = await createTenant("renewal-cancel-future", "growth");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "growth", "monthly");
    await subscriptionRepo.cancelSubscription(
      tenant.org.id,
      toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z")),
    );

    await runBillingRenewalJob(new Date("2026-02-01T00:00:00.000Z"));

    const updated = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(updated?.status).toBe("canceled");
    expect(updated?.plan).toBe("growth");
  });

  it("leaves trialing subscriptions untouched", async () => {
    const tenant = await createTenant("renewal-trial", "growth");
    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(before?.status).toBe("trialing");

    await runBillingRenewalJob(new Date("2099-01-01T00:00:00.000Z"));

    const after = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(after?.status).toBe("trialing");
    expect(after?.currentPeriodEnd).toBe(before?.currentPeriodEnd);
  });

  it("prorates added seats on an active paid plan", async () => {
    const tenant = await createTenant("prorate-seats", "starter");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "starter", "monthly");
    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);
    await subscriptionRepo.advancePeriod(
      tenant.org.id,
      toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z")),
      toIsoTimestamp(new Date("2026-01-31T00:00:00.000Z")),
    );

    // 10 days left of a 30 day period, adding 1 seat at 900 cents/mo.
    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 3,
    });

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(1);
    // Can't control "now" inside updateSeats directly here since it uses real time;
    // just assert an invoice happened with a positive, bounded amount.
    expect(invoices[0].amountCents).toBeGreaterThanOrEqual(0);
    expect(invoices[0].amountCents).toBeLessThanOrEqual(900);
  });
});

