import { afterAll, beforeAll, describe, expect, it } from "vitest";

import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

const DAY_MS = 24 * 60 * 60 * 1000;

describe("sanity: changePlan proration", () => {
  it("charges the prorated price difference for a paid-to-paid upgrade while active", async () => {
    const tenant = await createTenant("plan-upgrade", "starter");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "starter", "monthly");
    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);
    const periodStart = new Date(Date.now() - 20 * DAY_MS);
    const periodEnd = new Date(Date.now() + 10 * DAY_MS);
    await subscriptionRepo.advancePeriod(
      tenant.org.id,
      toIsoTimestamp(periodStart),
      toIsoTimestamp(periodEnd),
    );

    // starter 900 -> growth 1900, diff 1000/seat/mo, 2 seats, ~10/30 days left.
    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(1);
    expect(invoices[0].amountCents).toBeGreaterThan(0);
    expect(invoices[0].amountCents).toBeLessThanOrEqual(2000);

    const updated = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(updated?.currentPeriodStart).toBe(toIsoTimestamp(periodStart));
    expect(updated?.currentPeriodEnd).toBe(toIsoTimestamp(periodEnd));
  });

  it("charges nothing for a downgrade or an unchanged plan", async () => {
    const tenant = await createTenant("plan-downgrade", "growth");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "growth", "monthly");
    await subscriptionRepo.updateSeatCount(tenant.org.id, 1);
    await subscriptionRepo.advancePeriod(
      tenant.org.id,
      toIsoTimestamp(new Date(Date.now() - 1 * DAY_MS)),
      toIsoTimestamp(new Date(Date.now() + 20 * DAY_MS)),
    );

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });
    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    expect((await invoiceRepo.listInvoices(tenant.org.id)).length).toBe(0);
  });

  it("charges nothing and keeps the trial period when choosing a plan during a trial", async () => {
    const tenant = await createTenant("plan-trial", "growth");
    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(before?.status).toBe("trialing");

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    expect((await invoiceRepo.listInvoices(tenant.org.id)).length).toBe(0);
    const after = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(after?.currentPeriodStart).toBe(before?.currentPeriodStart);
    expect(after?.currentPeriodEnd).toBe(before?.currentPeriodEnd);
  });

  it("starts a fresh, fully-invoiced period when leaving the free plan", async () => {
    const tenant = await createTenant("plan-leave-free", "free");
    const before = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(before?.plan).toBe("free");

    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(1);
    expect(invoices[0].amountCents).toBe(900 * 2 * 1);

    const after = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(after?.currentPeriodStart).not.toBe(before?.currentPeriodStart);
  });

  it("charges nothing moving to the free plan", async () => {
    const tenant = await createTenant("plan-to-free", "growth");
    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "growth", "monthly");
    await subscriptionRepo.advancePeriod(
      tenant.org.id,
      toIsoTimestamp(new Date(Date.now() - 1 * DAY_MS)),
      toIsoTimestamp(new Date(Date.now() + 20 * DAY_MS)),
    );

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "free",
      interval: "monthly",
    });

    expect((await invoiceRepo.listInvoices(tenant.org.id)).length).toBe(0);
  });
});

