import * as activityRepo from "@/server/repositories/activity-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("sanity: invoice fan-out", () => {
  it("emits billing.invoice_issued, records the audit row and notifies the owner", async () => {
    const tenant = await createTenant("invoice-fanout", "free");
    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);

    const seen: unknown[] = [];
    let off: Unsubscribe | undefined;
    off = subscribe("billing.invoice_issued", (payload) => {
      seen.push(payload);
    });

    await billingService.changePlan(tenant.actors.admin, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    off();
    expect(seen.length).toBe(1);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    const found = activity.items.find((e) => e.action === "billing.invoice_issued");
    expect(found).toBeTruthy();
    expect(found?.subjectKind).toBe("subscription");
    expect(found?.subjectId).toBe(tenant.org.id);

    const notifications = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    const invoiceNotif = notifications.items.find((n) => n.kind === "invoice_issued");
    expect(invoiceNotif).toBeTruthy();
  });

  void toIsoTimestamp;
});

